package com.enjoyyourtime.globalfitness.food

import com.enjoyyourtime.globalfitness.food.catalog.RecipeParser
import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The ingredients asset `assets/food/recipes.tsv` (generated by tools/food-db, contract 3 of 2026-11-02's
 * common.md): `dish ingredient grams adjustable`, every id a food of foods.tsv, grams of the ingredient (in its
 * own unit) in 100 g of the finished dish with one decimal, adjustable 0 or 1; and the app reads every row. The
 * file comes with the food data of 1.6.0: an app without it simply offers no ingredients, so there is nothing
 * to check before it is there.
 */
class RecipesTsvContractTest {
    private fun findRepoFile(path: String): File? =
        generateSequence(File(System.getProperty("user.dir")).absoluteFile) { it.parentFile }
            .map { File(it, path) }
            .firstOrNull { it.isFile }

    private val file = findRepoFile("app/src/main/assets/food/recipes.tsv")
    private val foods: Map<String, Map<String, String>> by lazy {
        val lines = findRepoFile("app/src/main/assets/food/foods.tsv")!!.readText(Charsets.UTF_8).split('\n').filter { it.isNotEmpty() }
        val header = lines.first().split('\t')
        lines.drop(1).map { header.zip(it.split('\t')).toMap() }.associateBy { it.getValue("id") }
    }

    @Test
    fun formatIdsAndAmounts() {
        val text = file?.readText(Charsets.UTF_8) ?: return
        assertTrue("LF line endings", '\r' !in text)
        val lines = text.split('\n').dropLastWhile { it.isEmpty() }
        assertEquals(listOf("dish", "ingredient", "grams", "adjustable"), lines.first().split('\t'))
        val seen = HashSet<Pair<String, String>>()
        for (line in lines.drop(1)) {
            val cells = line.split('\t')
            assertEquals(line, 4, cells.size)
            val (dish, ingredient, grams, adjustable) = cells
            assertTrue("$line: dish is a food", dish in foods)
            assertTrue("$line: ingredient is a food", ingredient in foods)
            assertTrue("$line: a dish is not its own ingredient", dish != ingredient)
            assertTrue("$line: grams with at most one decimal", Regex("\\d+(\\.\\d)?").matches(grams))
            assertTrue("$line: grams > 0", grams.toDouble() > 0)
            assertTrue("$line: adjustable 0 or 1", adjustable in setOf("0", "1"))
            assertTrue("$line: listed twice", seen.add(dish to ingredient))
        }
    }

    @Test
    fun theAppReadsEveryRow() {
        val text = file?.readText(Charsets.UTF_8) ?: return
        val rows = text.split('\n').drop(1).filter { it.isNotEmpty() }
        val recipes = RecipeParser.parse(text) { it in foods }
        assertEquals(rows.size, recipes.values.sumOf { it.size })
        // Every dish with ingredients lets the user change at least one of them (or why list it?).
        for ((dish, list) in recipes) assertTrue("$dish: nothing adjustable", list.any { it.adjustable })
    }
}
